/** 
 * Sets whether the entire tree under the base DN will be searched (recursive search) when doing LDAP queries (finding users, groups, etc). When false, only a single level under the base DN will be searched. The default is <tt>true</tt> which is the best option for most LDAP setups. In only a few cases will the directory be setup in such a way that it's better to do single level searching.
 * @param subTreeSearch true if the entire tree under the base DN will be searched.
 */
public void setSubTreeSearch(boolean subTreeSearch){
  this.subTreeSearch=subTreeSearch;
  try {
    properties.put("ldap.subTreeSearch",String.valueOf(subTreeSearch));
  } catch (UnsupportedOperationException | IllegalArgumentException e) {
    // Handle exception appropriately, e.g., log or throw a more specific exception
    throw new RuntimeException("Failed to set ldap.subTreeSearch property", e);
  }
}
